def open_neighbours(grid, r, c):
    count = 0
    if grid[r - 1][c] == ".":
        count += 1
    if r + 1 < len(grid) and grid[r + 1][c] == ".":
        count += 1
    if c - 1 >= 0 and grid[r][c - 1] == ".":
        count += 1
    if c + 1 < len(grid[0]) and grid[r][c + 1] == ".":
        count += 1
    return count

